package com.yuewei.plm.module.partner;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class SampleIdentityKeysTest {
 Map<String,Object> sample(){return new LinkedHashMap<>(Map.of("sourceType","catalog","catalogStyleId",1L,"phoneModelId",2L,"colorId",3L,"catalogConfigurationKey","version-A","supplierCode","SUP-A","name","原名"));}
 @Test void receiptQuantityLocationNameAndBatchDoNotChangeARealType(){var a=sample();var key=SampleIdentityKeys.from(a).key();a.putAll(Map.of("name","改名","location","墨西哥","qty",200,"receivedDate","2026-10-27","code","SP-000999"));assertThat(SampleIdentityKeys.from(a).key()).isEqualTo(key);}
 @Test void phoneColorConfigurationAndActualVersionCannotBeForcedTogetherByAReason(){for(var field:List.of("phoneModelId","colorId","catalogConfigurationKey","sampleVersion","supplierCode")){var a=sample();var b=sample();if(field.equals("sampleVersion")){a.put(field,"V1");b.put(field,"V2");}else b.put(field,field.endsWith("Id")?99L:"different");assertThatThrownBy(()->SampleIdentityKeys.compatible(a,b)).hasMessageContaining("不能合并不同实物");}}
 @Test void missingPhysicalIdentityNeverUsesNameAsAnAutomaticKey(){var a=new LinkedHashMap<String,Object>(Map.of("name","相同名称","sourceType","self"));assertThat(SampleIdentityKeys.from(a).exact()).isFalse();assertThat(SampleIdentityKeys.from(a).key()).isEmpty();}
 @Test void phoneDummyVersionsAreDifferentKindsButNeverPerUnitNumbers(){var a=new LinkedHashMap<String,Object>(Map.of("sourceType","device","phoneModelId",2,"sampleKind","dummy","sampleVersion","V1","assetNumber","piece1"));var first=SampleIdentityKeys.from(a).key();a.put("assetNumber","piece2");assertThat(SampleIdentityKeys.from(a).key()).isEqualTo(first);a.put("sampleVersion","V2");assertThat(SampleIdentityKeys.from(a).key()).isNotEqualTo(first);}
 @Test void cpAndPsKeepCanonicalExactPhysicalIdentity(){var a=sample();a.put("specId",10L);var b=sample();b.put("specId",11L);assertThatCode(()->SampleIdentityKeys.compatible(a,b)).doesNotThrowAnyException();b.put("catalogStyleId",99L);assertThatThrownBy(()->SampleIdentityKeys.compatible(a,b)).hasMessageContaining("目录款式");} @Test void anExplicitConfigurationReferenceCannotHideKnownMaterialOrStructureChanges(){var first=sample();first.put("sourceSnapshot",Map.of("material","PC","configuration","磁吸支架A"));var changed=sample();changed.put("sourceSnapshot",Map.of("material","TPU","configuration","磁吸支架A"));var a=SampleIdentityKeys.from(first);var b=SampleIdentityKeys.from(changed);assertThat(a.key()).isEqualTo(b.key());assertThatThrownBy(()->SampleIdentityKeys.compatible(a.basis(),b.basis())).hasMessageContaining("材料");changed.put("sourceSnapshot",Map.of("material","PC","configuration","不同支架B"));assertThatThrownBy(()->SampleIdentityKeys.compatible(a.basis(),SampleIdentityKeys.from(changed).basis())).hasMessageContaining("结构配置");}
 @Test void modelProjectProvenanceDoesNotSplitAnUnchangedRealProductPhoneVersion(){var a=new LinkedHashMap<String,Object>(Map.of("sourceType","model","modelProductId",7L,"phoneModelId",2L,"sampleVersion","V1","projectId",10L));var b=new LinkedHashMap<>(a);b.put("projectId",20L);assertThat(SampleIdentityKeys.from(a).key()).isEqualTo(SampleIdentityKeys.from(b).key());assertThatCode(()->SampleIdentityKeys.compatible(SampleIdentityKeys.from(a).basis(),SampleIdentityKeys.from(b).basis())).doesNotThrowAnyException();}
 @Test void aPhoneDeviceCannotBeExplicitlyMergedIntoAProductSample(){var a=sample();var b=new LinkedHashMap<String,Object>(Map.of("sourceType","device","phoneModelId",2L,"sampleKind","phone"));assertThatThrownBy(()->SampleIdentityKeys.compatible(SampleIdentityKeys.from(a).basis(),SampleIdentityKeys.from(b).basis())).hasMessageContaining("不是同一种实物");}
 @Test void pendingCooperativeSamplesRemainInTheirKnownBusinessDomainWithoutAnAutomaticMergeKey(){var a=sample();a.put("pending",true);var evidence=SampleIdentityKeys.from(a);assertThat(evidence.domain()).isEqualTo("partner");assertThat(evidence.exact()).isFalse();assertThat(evidence.key()).isEmpty();}

}
